const TIME_ZONE = 'America/Mexico_City';

// Obtiene el offset (en minutos) entre "date" (instante real UTC) y cómo se representaría en timeZone.
// Técnica estándar con Intl.DateTimeFormat + formatToParts.
function getTimeZoneOffsetMinutes(date, timeZone) {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone,
    hour12: false,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  });

  const parts = dtf.formatToParts(date);
  const vals = {};
  for (const p of parts) {
    if (p.type !== 'literal') vals[p.type] = p.value;
  }

  // Esta fecha/hora es "lo que marca el reloj" en esa zona, pero lo interpretamos como UTC para comparar.
  const asUTC = Date.UTC(
    Number(vals.year),
    Number(vals.month) - 1,
    Number(vals.day),
    Number(vals.hour),
    Number(vals.minute),
    Number(vals.second)
  );

  // Diferencia entre el "reloj" de la zona y el instante real => offset en minutos
  return (asUTC - date.getTime()) / 60000;
}

// Convierte componentes (YYYY,MM,DD,HH,mm) entendidos como timeZone a timestamp UTC (ms)
function zonedDateTimeToUtcMillis({ year, month, day, hour, minute }, timeZone) {
  // 1) Hacemos un guess: interpretamos esos componentes como si fueran UTC
  let utcGuess = Date.UTC(year, month - 1, day, hour, minute, 0);

  // 2) Calculamos offset de la zona para ese instante aproximado
  let guessDate = new Date(utcGuess);
  let offsetMin = getTimeZoneOffsetMinutes(guessDate, timeZone);

  // 3) Ajustamos: si en esa zona eran "hora local", restamos el offset para obtener UTC real
  let utcMillis = utcGuess - offsetMin * 60_000;

  // 4) Recalcular una vez más por si el offset cambia (DST / transiciones)
  // (CDMX normalmente no cambia hoy, pero esto lo hace robusto)
  guessDate = new Date(utcMillis);
  offsetMin = getTimeZoneOffsetMinutes(guessDate, timeZone);
  utcMillis = utcGuess - offsetMin * 60_000;

  return utcMillis;
}

// Para debug: formatea un Date en CDMX sin librerías
function formatInZone(date, timeZone) {
  return new Intl.DateTimeFormat('es-MX', {
    timeZone,
    hour12: false,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    timeZoneName: 'short',
  }).format(date);
}

// ==== Tu lógica ====
const nowMillis = Date.now();
const results = [];

for (const item of $input.all()) {
  const data = item.json;

  try {
    const [day, month, year] = data.dia.split('-').map(Number);
    const [hours, minutes] = data.hora.split(':').map(Number);

    // Evento interpretado como America/Mexico_City -> convertido a UTC ms
    const eventMillis = zonedDateTimeToUtcMillis(
      { year, month, day, hour: hours, minute: minutes },
      TIME_ZONE
    );

    const diffMs = eventMillis - nowMillis;
    const diffHours = diffMs / (1000 * 60 * 60);

    let category = 'skip';
    if (diffMs < 0) {
      category = 'delete';
    } else if (diffHours <= 1 && diffHours > 0) {
      category = '1hour';
    } else if (diffHours <= 12 && diffHours > 1) {
      category = '12hours';
    } else if (diffHours <= 24 && diffHours > 12) {
      category = '24hours';
    }

    results.push({
      json: {
        ...data,
        category,
        diffHours: Math.round(diffHours * 100) / 100,

        // Debug para que veas exactamente qué está pasando:
        now_cdmx: formatInZone(new Date(nowMillis), TIME_ZONE),
        event_cdmx: formatInZone(new Date(eventMillis), TIME_ZONE),
        now_utc: new Date(nowMillis).toISOString(),
        event_utc: new Date(eventMillis).toISOString(),
      },
    });
  } catch (error) {
    results.push({ json: { ...data, category: 'skip', error: error.message } });
  }
}

return results;

